{
  "findings": [
    {
      "check_id": "CKV_AWS_21",
      "title": "Ensure all data stored in the S3 bucket have versioning enabled",
      "resource": "aws_s3_bucket.b",
      "severity": "HIGH",
      "explanation": "Versioning is not enabled on the S3 bucket. Without versioning, data recovery in case of accidental deletion or overwrites is not possible."
    },
    {
      "check_id": "CKV2_AWS_6",
      "title": "Ensure that S3 bucket has a Public Access block",
      "resource": "aws_s3_bucket.b",
      "severity": "MEDIUM",
      "explanation": "The S3 bucket does not have a Public Access block configured. This increases the risk of unintentional public exposure of the bucket or its objects."
    },
    {
      "check_id": "CKV_AWS_18",
      "title": "Ensure the S3 bucket has access logging enabled",
      "resource": "aws_s3_bucket.b",
      "severity": "MEDIUM",
      "explanation": "Access logging is not enabled for the S3 bucket. Without logging, it is difficult to track access patterns and detect unauthorized access."
    },
    {
      "check_id": "CKV_AWS_145",
      "title": "Ensure that S3 buckets are encrypted with KMS by default",
      "resource": "aws_s3_bucket.b",
      "severity": "MEDIUM",
      "explanation": "The S3 bucket does not have default encryption enabled using AWS KMS. This could lead to sensitive data being stored unencrypted."
    }
  ],
  "patched_code": "resource \"aws_s3_bucket\" \"b\" {\n  bucket = \"my-tf-test-bucket-ggff\"\n  acl    = \"private\"\n\n  versioning {\n    enabled = true\n  }\n\n  server_side_encryption_configuration {\n    rule {\n      apply_server_side_encryption_by_default {\n        kms_master_key_id = \"alias/aws/s3\"\n        sse_algorithm     = \"aws:kms\"\n      }\n    }\n  }\n\n  logging {\n    target_bucket = \"my-tf-test-bucket-logs\"\n    target_prefix = \"log/\"\n  }\n\n  public_access_block {\n    block_public_acls       = true\n    block_public_policy     = true\n    ignore_public_acls      = true\n    restrict_public_buckets = true\n  }\n}\n\nresource \"aws_s3_bucket\" \"b_logs\" {\n  bucket = \"my-tf-test-bucket-logs\"\n  acl    = \"log-delivery-write\"\n}",
  "fix_summary": "Enabled versioning for data recovery, added server-side encryption with AWS KMS for data protection, configured access logging to a dedicated logging bucket, and added a Public Access block to prevent unintentional public exposure."
}
